import json,subprocess,sys,unittest

class CompilerContextRegressionTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        ReadinessKernelTests.setUpClass.__func__(cls)
    # Mechanical projections of the real approved Atom10 request and captured
    # graph. These mutations are not independent semantic judgments or evidence
    # that the whole machinery has a settled candidate plan.
    approved_request = json.loads("{\"schema_version\":1,\"atomic_step_id\":\"readiness-10-atom-candidate-compiler\",\"outcome\":\"Implement atom-candidate admission, requirement and verification coverage, dependency ordering, two-seat cohesion gating, and byte-stable compilation to the current Atom Building request schema.\",\"practical_value\":\"A settled feature can become small independently testable implementation atoms without hiding missing scope, prerequisites, cases, or a second behavior.\",\"stopping_condition\":\"Stop when a complete candidate set compiles in deterministic topological order to exact eight-field Atom Building requests and every incomplete, cyclic, incohesive, unverified, or blocker-linked candidate is refused.\",\"allowed_paths\":[\"skills/requirement-to-atom-readiness-machinery/references/atom-handoff-contract.md\",\"skills/requirement-to-atom-readiness-machinery/schemas/atom-candidates.schema.json\",\"skills/requirement-to-atom-readiness-machinery/scripts/readiness_controller.py\",\"tests/test_requirement_to_atom_readiness.py\"],\"captured_cases\":[{\"case_id\":\"a10-success-current-abm-schema\",\"source_ref\":\"Tasks/requirement-to-atom-readiness-machinery/implementation-atom-cases.md\",\"sha256\":\"434c6d1945ee1f5d1362246d5020b402e09e0ee39985a2f226f55358175d9934\",\"kind\":\"success\",\"expected_outcome\":\"Complete cohesive candidates compile byte-stably in dependency order to requests with exactly the current Atom Building fields.\"},{\"case_id\":\"a10-failure-incomplete-or-incohesive\",\"source_ref\":\"Tasks/requirement-to-atom-readiness-machinery/implementation-atom-cases.md\",\"sha256\":\"434c6d1945ee1f5d1362246d5020b402e09e0ee39985a2f226f55358175d9934\",\"kind\":\"failure\",\"expected_outcome\":\"Incomplete, cyclic, incohesive, unverified, or blocker-linked candidates cannot compile or reach readiness.\"}],\"contract_surface\":{\"kind\":\"validation\",\"deliverable\":\"atom_controller\",\"fields\":[{\"field\":\"allowed_paths\",\"shape\":\"list\",\"shape_source\":\"skills/atom-building-machinery/scripts/atom_controller.py::REQUEST_FIELDS\"},{\"field\":\"captured_cases\",\"shape\":\"list\",\"shape_source\":\"skills/atom-building-machinery/scripts/atom_controller.py::REQUEST_FIELDS\"},{\"field\":\"contract_surface\",\"shape\":\"object\",\"shape_source\":\"skills/atom-building-machinery/scripts/atom_controller.py::REQUEST_FIELDS\"}]}}")

    def candidate_context(self):
        import copy
        graph = copy.deepcopy(EvidenceGraphRuntimeTests.captured_graph)
        wrapped = {'graph':graph, 'graph_sha256':self.module.digest(self.module.canonical(graph)),
                   'queue':graph['conditions'], 'next_action':graph['conditions'][0],
                   'status':'blocked','readiness':'not-assessed'}
        requirements = [n['id'] for n in graph['nodes'] if n['type']=='requirement']
        row = {**copy.deepcopy(self.approved_request), 'requirement_ids':requirements,
               'prerequisite_atom_ids':[], 'verification_ids':[],
               'authority_decision_ids':[], 'evidence_ids':[]}
        checked = {'plan_event_sha256':'a'*64, 'plan_node_id':graph['conditions'][0]['node_id'],
                   'graph_sha256':wrapped['graph_sha256'],
                   'order':[row['atomic_step_id']], 'candidates':[row]}
        return wrapped, checked, row

    def test_old_set_judgment_cannot_compile_unchanged_candidate(self):
        from unittest.mock import patch
        k=self.module; graph,checked,row=self.candidate_context()
        state=k.initial_interview_state();state['candidate_set']=checked
        state['proposals']=[{'family':'atom-cohesion','verdict':'cohesive',
            'candidate_sha256':k.digest(k.canonical(row)), 'candidate_set_sha256':'0'*64}]
        with patch.object(k,'checked_candidates',return_value=(checked,graph,{},set(self.approved_request))):
            with self.assertRaisesRegex(k.Refused,'no matching two-seat'):
                k.candidate_payload(None,None,graph,state,compile_output=True)

    def test_current_split_judgment_routes_back_to_planning(self):
        k=self.module;graph,checked,row=self.candidate_context()
        state=k.initial_interview_state();state['candidate_set']=checked
        state['proposals']=[{'family':'atom-cohesion','verdict':'must_split',
            'candidate_sha256':k.digest(k.canonical(row)),
            'candidate_set_sha256':k.digest(k.canonical(checked))}]
        result=k.routed_graph(graph,state)
        item=next(q for q in result['queue'] if q['node_id']==checked['plan_node_id'])
        self.assertEqual(item['blocking_class'],'planning')
        state['proposals'][0]['candidate_set_sha256']='0'*64
        result=k.routed_graph(graph,state)
        item=next(q for q in result['queue'] if q['node_id']==checked['plan_node_id'])
        self.assertNotEqual(item['blocking_class'],'planning')

from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
class ReadinessSchemaTests(unittest.TestCase):
    def test_schema_cli(self):
        path=ROOT/"skills/requirement-to-atom-readiness-machinery/scripts/readiness_controller.py"
        command=[sys.executable,str(path),"schema"]
        first=subprocess.run(command,capture_output=True,text=True)
        self.assertEqual(first.returncode,0)
        self.assertEqual(first.stdout,subprocess.check_output(command,text=True))
        schema=json.loads(first.stdout)
        self.assertEqual(schema,json.loads((ROOT/"skills/requirement-to-atom-readiness-machinery/schemas/readiness-request.schema.json").read_text()))
        self.assertFalse(schema["additionalProperties"])
        self.assertEqual(len(schema["properties"]["machinery_contracts"]["allOf"]),12)
        self.assertEqual(subprocess.run(command+[str(path)],capture_output=True).returncode,2)

class ReadinessKernelTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        import importlib.util
        spec=importlib.util.spec_from_file_location('kernel',ROOT/'skills/requirement-to-atom-readiness-machinery/scripts/readiness_controller.py')
        cls.module=importlib.util.module_from_spec(spec);spec.loader.exec_module(cls.module)
    def test_duplicate_and_nonfinite_json(self):
        for raw in [b'{"a":1,"a":2}',b'{"a":NaN}',b'\xef\xbb\xbf{}']:
            with self.assertRaises(self.module.Refused):self.module.decode(raw,'test')
    def test_canonical_chain(self):
        m=self.module;events=m.chain([('run_started',{'request_sha256':'a'*64}),('input_admitted',{'identity':'captured'})])
        self.assertEqual(events[0]['previous'],m.GENESIS)
        self.assertEqual(events[1]['previous'],events[0]['sha256'])
        self.assertEqual(events,m.chain([('run_started',{'request_sha256':'a'*64}),('input_admitted',{'identity':'captured'})]))
    def test_tip_guard(self):
        self.module.require_tip('a'*64,'a'*64)
        for bad in [True,None,'a'*64+'\n','b'*64]:
            with self.assertRaises(self.module.Refused):self.module.require_tip(bad,'a'*64)
    def test_path_contract(self):
        for path in ['relative','/a/../b','/a//b','/a/']:
            with self.assertRaises(self.module.Refused):self.module.absolute(path)

    def test_package_contract_and_unsafe_member_paths(self):
        m=self.module.package_module()
        schema=m.package_schema()
        self.assertEqual(schema,json.loads((ROOT/'skills/requirement-to-atom-readiness-machinery/schemas/readiness-package.schema.json').read_bytes()))
        member=schema['properties']['members']['items']
        import re
        for path in ('manifest.json','../file','a/../b','..','a/..','/absolute','a//b'):
            self.assertIsNone(re.fullmatch(member['properties']['path']['pattern'],path))
        self.assertEqual(schema['properties']['approval_state']['enum'],['not-approved','approved','rejected'])

    def test_package_missing_graph_never_grants_readiness(self):
        m=self.module.package_module()
        with self.assertRaisesRegex(self.module.Refused,'no admitted requirement graph'):
            m.verdict(self.module,None,self.module.initial_interview_state())

    def test_package_renderer_is_bound_to_runtime_identity(self):
        from unittest.mock import patch
        k=self.module;before=k.adapter_code_sha256();read=k.read_file
        def changed(path,limit):
            raw=read(path,limit)
            return raw+b' ' if Path(path).name=='package_renderer.py' else raw
        with patch.object(k,'read_file',side_effect=changed):
            self.assertNotEqual(k.adapter_code_sha256(),before)


class ReadinessUpstreamTests(ReadinessKernelTests):
    def test_adapter_sources_are_bound_to_controller_identity(self):
        from unittest.mock import patch
        m = self.module
        expected = m.adapter_code_sha256()
        original = m.read_file
        def changed(path, limit):
            raw = original(path, limit)
            return raw + b" " if Path(path).name == "requirements_adapter.py" else raw
        with patch.object(m, "read_file", side_effect=changed):
            self.assertNotEqual(m.adapter_code_sha256(), expected)

    def test_upstream_errors_are_explicit_refusals(self):
        from unittest.mock import patch
        m = self.module
        with patch.object(m, "_verify_upstreams", side_effect=ValueError("missing sealed evidence")):
            with self.assertRaisesRegex(m.Refused, "upstream verification refused.*missing sealed evidence"):
                m.verify_upstreams({}, None)

    def test_installed_runtime_is_fixed_local_code(self):
        files, runtime, *_ = self.module.upstream_modules()
        self.assertEqual(files["requirements-exporter"], ROOT / "skills/requirements-machinery/scripts/cover.py")
        self.assertEqual(set(runtime), {p.name for p in files["requirements-exporter"].parent.glob("*.py")})
        self.assertEqual(runtime["cover.py"], files["requirements-exporter"].read_bytes())


class EvidenceGraphSchemaTests(unittest.TestCase):
    def test_closed_evidence_and_graph_cli(self):
        from jsonschema import Draft202012Validator
        module=ROOT/'skills/requirement-to-atom-readiness-machinery/scripts/evidence_adapter.py'
        for name,file in [('evidence','evidence-manifest.schema.json'),('graph','graph.schema.json')]:
            command=[sys.executable,str(module),'schema',name]
            raw=subprocess.check_output(command,text=True)
            self.assertEqual(raw,subprocess.check_output(command,text=True))
            schema=json.loads(raw);Draft202012Validator.check_schema(schema)
            self.assertEqual(schema,json.loads((module.parents[1]/'schemas'/file).read_text()))
            self.assertFalse(schema['additionalProperties'])
            self.assertEqual(len(schema['$defs']['node']['oneOf']),6)
            self.assertEqual(subprocess.run(command+[str(module)],capture_output=True).returncode,2)


